function Invoke-VulnerabilityScanLocal {
    param([string]$ComputerName = $env:COMPUTERNAME)
    $vulns = @()
    # Missing Updates
    $updates = Get-HotFix -ComputerName $ComputerName -ErrorAction SilentlyContinue
    if ($updates.Count -lt 50) { $vulns += [PSCustomObject]@{Type='PatchLevel'; Severity='High'; Finding='Peu de correctifs installés' } }
    # AlwaysInstallElevated
    if ((Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Installer' -Name AlwaysInstallElevated -ErrorAction SilentlyContinue).AlwaysInstallElevated -eq 1) {
        $vulns += [PSCustomObject]@{Type='PrivilegeEscalation'; Severity='Critical'; Finding='AlwaysInstallElevated enabled' }
    }
    # Unquoted Service Paths
    Get-CimInstance Win32_Service | Where-Object { $_.PathName -match '^"?[^"]+\\[^" ]+\\' } | ForEach-Object {
        $vulns += [PSCustomObject]@{Type='UnquotedPath'; Severity='High'; Service=$_.Name; Path=$_.PathName }
    }
    Write-SysLog "TH: Local vulnerability scan completed on $ComputerName - $($vulns.Count) findings"
    return $vulns
}

function Search-ActiveDirectoryThreats {
    param([string]$Domain = $DomainFQDN)
    $findings = @()
    # Kerberoasting
    $spnUsers = Get-ADUser -Filter {ServicePrincipalName -ne "$null"} -Properties ServicePrincipalName
    if ($spnUsers.Count -gt 0) { $findings += [PSCustomObject]@{Risk='Kerberoasting'; Count=$spnUsers.Count; Severity='High'} }
    # DCSync rights
    $dcsync = Get-ADObject -Filter { (msDS-AllowedToActOnBehalfOfOtherIdentity -ne $null) -or (msDS-AllowedToDelegateTo -ne $null) }
    Write-SysLog "TH: AD Threat scan completed"
    return $findings
}
